import React from 'react';

// Reusable liquid glass button component
export function BtnPrimary({ children, onClick, disabled, style = {} }) {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      style={{
        width: '100%',
        padding: '17px 24px',
        borderRadius: 999,           // fully round
        border: 'none',
        cursor: disabled ? 'default' : 'pointer',
        fontFamily: "'Inter', sans-serif",
        fontSize: 15,
        fontWeight: 600,
        letterSpacing: '-0.02em',
        color: disabled ? 'rgba(15,28,28,0.35)' : '#0F1C1C',
        position: 'relative',
        overflow: 'hidden',
        transition: 'all 0.2s',
        WebkitTapHighlightColor: 'transparent',
        background: disabled
          ? 'rgba(255,255,255,0.08)'
          : 'linear-gradient(160deg, rgba(200,240,240,0.95) 0%, rgba(126,200,200,0.88) 50%, rgba(45,160,160,0.92) 100%)',
        boxShadow: disabled ? 'none' : [
          '0 1px 0 rgba(255,255,255,0.65) inset',
          '0 -1px 0 rgba(0,0,0,0.08) inset',
          '0 8px 32px rgba(45,107,107,0.38)',
          '0 2px 8px rgba(45,107,107,0.22)',
        ].join(', '),
        ...style,
      }}
    >
      {/* top sheen */}
      <span style={{
        position: 'absolute', top: 0, left: 0, right: 0, height: '50%',
        background: 'linear-gradient(180deg, rgba(255,255,255,0.5) 0%, rgba(255,255,255,0) 100%)',
        borderRadius: '999px 999px 0 0',
        pointerEvents: 'none',
      }} />
      {children}
    </button>
  );
}

export function BtnSecondary({ children, onClick, style = {} }) {
  return (
    <button
      onClick={onClick}
      style={{
        width: '100%',
        padding: '16px 24px',
        borderRadius: 999,
        border: 'none',
        cursor: 'pointer',
        fontFamily: "'Inter', sans-serif",
        fontSize: 15,
        fontWeight: 500,
        letterSpacing: '-0.01em',
        color: 'rgba(238,234,227,0.65)',
        position: 'relative',
        overflow: 'hidden',
        transition: 'all 0.2s',
        WebkitTapHighlightColor: 'transparent',
        background: 'linear-gradient(160deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0.04) 100%)',
        boxShadow: [
          '0 1px 0 rgba(255,255,255,0.15) inset',
          '0 -1px 0 rgba(0,0,0,0.12) inset',
          '0 4px 16px rgba(0,0,0,0.2)',
          '0 0 0 1px rgba(255,255,255,0.08)',
        ].join(', '),
        ...style,
      }}
    >
      <span style={{
        position: 'absolute', top: 0, left: 0, right: 0, height: '50%',
        background: 'linear-gradient(180deg, rgba(255,255,255,0.1) 0%, transparent 100%)',
        borderRadius: '999px 999px 0 0',
        pointerEvents: 'none',
      }} />
      {children}
    </button>
  );
}

export function BtnSmall({ children, onClick, icon, style = {} }) {
  return (
    <button
      onClick={onClick}
      style={{
        flex: 1,
        padding: '13px 16px',
        borderRadius: 999,
        border: 'none',
        cursor: 'pointer',
        fontFamily: "'Inter', sans-serif",
        fontSize: 12,
        fontWeight: 600,
        letterSpacing: '-0.01em',
        color: 'rgba(238,234,227,0.6)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 8,
        position: 'relative',
        overflow: 'hidden',
        transition: 'all 0.2s',
        WebkitTapHighlightColor: 'transparent',
        background: 'linear-gradient(160deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0.04) 100%)',
        boxShadow: [
          '0 1px 0 rgba(255,255,255,0.15) inset',
          '0 -1px 0 rgba(0,0,0,0.1) inset',
          '0 4px 12px rgba(0,0,0,0.18)',
          '0 0 0 1px rgba(255,255,255,0.07)',
        ].join(', '),
        ...style,
      }}
    >
      <span style={{ position: 'absolute', top: 0, left: 0, right: 0, height: '50%', background: 'linear-gradient(180deg, rgba(255,255,255,0.09) 0%, transparent 100%)', borderRadius: '999px 999px 0 0', pointerEvents: 'none' }} />
      {icon && <span style={{ color: '#7EC8C8', display: 'flex', alignItems: 'center', flexShrink: 0 }}>{icon}</span>}
      {children}
    </button>
  );
}
